import{_ as l,W as o,s as r,u as d,I as s,ah as i,w as n,Z as e,A as t}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const f=JSON.parse('{"title":"在 Fedora Linux 上使用 OpenCV（一） | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora Linux 上使用 OpenCV（一） | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"在 Fedora Linux 上使用 OpenCV（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora Linux 上使用 OpenCV（一） | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210802 Use OpenCV on Fedora Linux - part 1","title":"在 Fedora Linux 上使用 OpenCV（一）","tag":"202108"},"relativePath":"202108/20210802 Use OpenCV on Fedora Linux - part 1.md","filePath":"[post].md"}'),g={name:"202108/20210802 Use OpenCV on Fedora Linux - part 1.md"};function c(u,a,m,h,v,b){const p=o("Link");return d(),r("div",null,[a[31]||(a[31]=s("h1",{id:"在-fedora-linux-上使用-opencv-一",tabindex:"-1"},[n("在 Fedora Linux 上使用 OpenCV（一） "),s("a",{class:"header-anchor",href:"#在-fedora-linux-上使用-opencv-一","aria-label":"Permalink to 在 Fedora Linux 上使用 OpenCV（一）"},"​")],-1)),a[32]||(a[32]=s("p",null,[s("img",{src:"https://fedoramagazine.org/wp-content/uploads/2021/08/starry-night-1-816x345.jpg",alt:""})],-1)),s("p",null,[s("em",null,[a[1]||(a[1]=n("封面图片选自")),e(p,{href:"https://commons.wikimedia.org/wiki/File:Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg"},{default:t(()=>a[0]||(a[0]=[n("文森特·梵高")])),_:1}),a[2]||(a[2]=n("的《星空》，公共领域，通过维基共享资源发布"))])]),s("p",null,[a[5]||(a[5]=n("技术世界每天都在变化，对计算机视觉、人工智能和机器学习的需求也在增加。让计算机和手机能够看到周围环境的技术被称为 ")),e(p,{href:"https://en.wikipedia.org/wiki/Computer_vision"},{default:t(()=>a[3]||(a[3]=[n("计算机视觉")])),_:1}),a[6]||(a[6]=n("。这个重新创造人眼的工作始于 50 年代。从那时起，计算机视觉技术有了长足的发展。计算机视觉已经通过不同的应用进入了我们的手机。这篇文章将介绍 Fedora Linux 上的 ")),e(p,{href:"https://en.wikipedia.org/wiki/OpenCV"},{default:t(()=>a[4]||(a[4]=[n("OpenCV")])),_:1}),a[7]||(a[7]=n("。"))]),a[33]||(a[33]=s("h3",{id:"什么是-opencv",tabindex:"-1"},[n("什么是 OpenCV？ "),s("a",{class:"header-anchor",href:"#什么是-opencv","aria-label":"Permalink to 什么是 OpenCV？"},"​")],-1)),s("blockquote",null,[a[9]||(a[9]=s("p",null,[n("OpenCV（"),s("ruby",null,[n("开源计算机视觉库"),s("rt",null,"Open Source Computer Vision Library")]),n("）是一个开源的计算机视觉和机器学习软件库。OpenCV 的建立是为了给计算机视觉应用提供一个通用的基础设施，并加速机器感知在商业产品中的应用。它有超过 2500 种优化后的算法，其中包括一套全面的经典和最先进的计算机视觉和机器学习算法。这些算法可用于检测和识别人脸、识别物体、对视频中的人类行为进行分类，并建立标记，将其与增强现实叠加等等。")],-1)),s("p",null,[e(p,{href:"https://opencv.org/about/"},{default:t(()=>a[8]||(a[8]=[n("opencv.org – about")])),_:1})])]),a[34]||(a[34]=i(`<h3 id="在-fedora-linux-上安装-opencv" tabindex="-1">在 Fedora Linux 上安装 OpenCV <a class="header-anchor" href="#在-fedora-linux-上安装-opencv" aria-label="Permalink to 在 Fedora Linux 上安装 OpenCV">​</a></h3><p>要开始使用 OpenCV，请从 Fedora Linux 仓库中安装它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install opencv opencv-contrib opencv-doc python3-opencv python3-matplotlib python3-numpy</span></span></code></pre></div><p><strong>注意：</strong> 在 Fedora Silverblue 或 CoreOS 上，Python 3.9 是核心提交的一部分。用以下方法安装 OpenCV 和所需工具：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rpm-ostree install opencv opencv-doc python3-opencv python3-matplotlib python3-numpy</span></span></code></pre></div><p>接下来，在终端输入以下命令，以验证 OpenCV 是否已经安装：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ python</span></span>
<span class="line"><span>Python 3.9.6 (default, Jul 16 2021, 00:00:00)</span></span>
<span class="line"><span>[GCC 11.1.1 20210531 (Red Hat 11.1.1-3)] on linux</span></span>
<span class="line"><span>Type &quot;help&quot;, &quot;copyright&quot;, &quot;credits&quot; or &quot;license&quot; for more information.</span></span>
<span class="line"><span>&gt;&gt;&gt; import cv2 as cv</span></span>
<span class="line"><span>&gt;&gt;&gt; print( cv.__version__ )</span></span>
<span class="line"><span>4.5.2</span></span>
<span class="line"><span>&gt;&gt;&gt; exit()</span></span></code></pre></div><p>当你输入 <code>print</code> 命令时，应该显示当前的 OpenCV 版本，如上图所示。这表明 OpenCV 和 Python-OpenCV 库已经成功安装。</p>`,8)),s("p",null,[a[11]||(a[11]=n("此外，如果你想用 Jupyter Notebook 做笔记和写代码，并了解更多关于数据科学工具的信息，请查看早期的 Fedora Magazine 文章：")),e(p,{href:"https://fedoramagazine.org/jupyter-and-data-science-in-fedora/"},{default:t(()=>a[10]||(a[10]=[n("Fedora 中的 Jupyter 和数据科学")])),_:1}),a[12]||(a[12]=n("。"))]),a[35]||(a[35]=i(`<h3 id="开始使用-opencv" tabindex="-1">开始使用 OpenCV <a class="header-anchor" href="#开始使用-opencv" aria-label="Permalink to 开始使用 OpenCV">​</a></h3><p>安装完成后，使用 Python 和 OpenCV 库加载一个样本图像（按 <code>S</code> 键以 png 格式保存图像的副本并完成程序）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cp /usr/share/opencv4/samples/data/starry_night.jpg .</span></span>
<span class="line"><span>$ python starry_night.py</span></span></code></pre></div><p><code>starry_night.py</code> 的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import cv2 as cv</span></span>
<span class="line"><span>import sys</span></span>
<span class="line"><span>img = cv.imread(cv.samples.findFile(&quot;starry_night.jpg&quot;))</span></span>
<span class="line"><span>if img is None:</span></span>
<span class="line"><span>    sys.exit(&quot;Could not read the image.&quot;)</span></span>
<span class="line"><span>cv.imshow(&quot;Display window&quot;, img)</span></span>
<span class="line"><span>k = cv.waitKey(0)</span></span>
<span class="line"><span>if k == ord(&quot;s&quot;):</span></span>
<span class="line"><span>    cv.imwrite(&quot;starry_night.png&quot;, img)</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/06/image.png" alt=""></p><p>通过在 <code>cv.imread</code> 函数中添加参数 <code>0</code>，对图像进行灰度处理，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>img = cv.imread(cv.samples.findFile(&quot;starry_night.jpg&quot;),0)</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/06/image-1.png" alt=""></p><p>这些是一些可以用于 <code>cv.imread</code> 函数的第二个参数的替代值：</p><ul><li><code>cv2.IMREAD_GRAYSCALE</code> 或 <code>0</code>：以灰度模式加载图像。</li><li><code>cv2.IMREAD_COLOR** 或 </code>1\`：以彩色模式载入图像。图像中的任何透明度将被移除。这是默认的。</li><li><code>cv2.IMREAD_UNCHANGED** 或 </code>-1\`：载入未经修改的图像。包括 alpha 通道。</li></ul><h4 id="使用-opencv-显示图像属性" tabindex="-1">使用 OpenCV 显示图像属性 <a class="header-anchor" href="#使用-opencv-显示图像属性" aria-label="Permalink to 使用 OpenCV 显示图像属性">​</a></h4><p>图像属性包括行、列和通道的数量、图像数据的类型、像素的数量等等。假设你想访问图像的形状和它的数据类型。你可以这样做：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import cv2 as cv</span></span>
<span class="line"><span></span></span>
<span class="line"><span>img = cv.imread(cv.samples.findFile(&quot;starry_night.jpg&quot;))</span></span>
<span class="line"><span>print(&quot;Image size is&quot;, img.shape)</span></span>
<span class="line"><span>print(&quot;Data type of image is&quot;, img.dtype)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Image size is (600, 752, 3)</span></span>
<span class="line"><span>Data type of image is uint8</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(f&quot;Image 2D numpy array \\n {img}&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Image 2D numpy array</span></span>
<span class="line"><span> [[[0 0 0]</span></span>
<span class="line"><span>  [0 0 0]</span></span>
<span class="line"><span>  [0 0 0]</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>  [0 0 0]</span></span>
<span class="line"><span>  [0 0 0]</span></span>
<span class="line"><span>  [0 0 0]]</span></span>
<span class="line"><span></span></span>
<span class="line"><span> [[0 0 0]</span></span>
<span class="line"><span>  [0 0 0]</span></span>
<span class="line"><span>  [0 0 0]</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><ul><li><code>img.shape</code>：返回一个行数、列数和通道数的元组（如果是彩色图像）。</li><li><code>img.dtype</code>：返回图像的数据类型。</li></ul><p>接下来用 Matplotlib 显示图像：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import cv2 as cv</span></span>
<span class="line"><span>import matplotlib.pyplot as plt</span></span>
<span class="line"><span>img = cv.imread(cv.samples.findFile(&quot;starry_night.jpg&quot;),0)</span></span>
<span class="line"><span>plt.imshow(img)</span></span>
<span class="line"><span>plt.show()</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/06/image-2.png" alt=""></p><h4 id="发生了什么" tabindex="-1">发生了什么？ <a class="header-anchor" href="#发生了什么" aria-label="Permalink to 发生了什么？">​</a></h4><p>该图像是作为灰度图像读入的，但是当使用 Matplotlib 的 <code>imshow</code> 函数时，它不一定会以灰度显示。这是因为 <code>imshow</code> 函数默认使用不同的颜色映射。要指定使用灰度颜色映射，请将 <code>imshow</code> 函数的第二个参数设置为 <code>cmap=&#39;gray&#39;</code>，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plt.imshow(img,cmap=&#39;gray&#39;)</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/06/image-3.png" alt=""></p><p>这个问题在以彩色模式打开图片时也会发生，因为 Matplotlib 期望图片为 RGB（红、绿、蓝）格式，而 OpenCV 则以 BGR（蓝、绿、红）格式存储图片。为了正确显示，你需要将 BGR 图像的通道反转。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import cv2 as cv</span></span>
<span class="line"><span>import matplotlib.pyplot as plt</span></span>
<span class="line"><span>img = cv.imread(cv.samples.findFile(&quot;starry_night.jpg&quot;),cv.IMREAD_COLOR)</span></span>
<span class="line"><span>fig, (ax1, ax2) = plt.subplots(1,2)</span></span>
<span class="line"><span>ax1.imshow(img)</span></span>
<span class="line"><span>ax1.set_title(&#39;BGR Colormap&#39;)</span></span>
<span class="line"><span>ax2.imshow(img[:,:,::-1])</span></span>
<span class="line"><span>ax2.set_title(&#39;Reversed BGR Colormap(RGB)&#39;)</span></span>
<span class="line"><span>plt.show()</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/06/image-4.png" alt=""></p><h4 id="分割和合并颜色通道" tabindex="-1">分割和合并颜色通道 <a class="header-anchor" href="#分割和合并颜色通道" aria-label="Permalink to 分割和合并颜色通道">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import cv2 as cv</span></span>
<span class="line"><span>import matplotlib.pyplot as plt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>img = cv.imread(cv.samples.findFile(&quot;starry_night.jpg&quot;),cv.IMREAD_COLOR)</span></span>
<span class="line"><span>b,g,r = cv.split(img)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fig,ax = plt.subplots(2,2)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ax[0,0].imshow(r,cmap=&#39;gray&#39;)</span></span>
<span class="line"><span>ax[0,0].set_title(&quot;Red Channel&quot;);</span></span>
<span class="line"><span>ax[0,1].imshow(g,cmap=&#39;gray&#39;)</span></span>
<span class="line"><span>ax[0,1].set_title(&quot;Green Channel&quot;);</span></span>
<span class="line"><span>ax[1,0].imshow(b,cmap=&#39;gray&#39;)</span></span>
<span class="line"><span>ax[1,0].set_title(&quot;Blue Channel&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Merge the individual channels into a BGR image</span></span>
<span class="line"><span>imgMerged = cv.merge((b,g,r))</span></span>
<span class="line"><span># Show the merged output</span></span>
<span class="line"><span>ax[1,1].imshow(imgMerged[:,:,::-1])</span></span>
<span class="line"><span>ax[1,1].set_title(&quot;Merged Output&quot;);</span></span>
<span class="line"><span>plt.show()</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/06/image-5.png" alt=""></p><ul><li><code>cv2.split</code>：将一个多通道数组分割成几个单通道数组。</li><li><code>cv2.merge</code>：将几个数组合并成一个多通道数组。所有的输入矩阵必须具有相同的大小。</li></ul><p><strong>注意：</strong> 白色较多的图像具有较高的颜色密度。相反，黑色较多的图像，其颜色密度较低。在上面的例子中，红色的密度是最低的。</p><h4 id="转换到不同的色彩空间" tabindex="-1">转换到不同的色彩空间 <a class="header-anchor" href="#转换到不同的色彩空间" aria-label="Permalink to 转换到不同的色彩空间">​</a></h4><p><code>cv2.cvtColor</code> 函数将一个输入图像从一个颜色空间转换到另一个颜色空间。在 RGB 和 BGR 色彩空间之间转换时，应明确指定通道的顺序（<code>RGB2BGR</code> 或 <code>BGR2RGB</code>）。<strong>注意，OpenCV 中的默认颜色格式通常被称为 RGB，但它实际上是 BGR（字节是相反的）。</strong> 因此，标准（24 位）彩色图像的第一个字节将是一个 8 位蓝色分量，第二个字节是绿色，第三个字节是红色。然后第四、第五和第六个字节将是第二个像素（蓝色、然后是绿色，然后是红色），以此类推。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import cv2 as cv</span></span>
<span class="line"><span>import matplotlib.pyplot as plt</span></span>
<span class="line"><span>img = cv.imread(cv.samples.findFile(&quot;starry_night.jpg&quot;),cv.IMREAD_COLOR)</span></span>
<span class="line"><span>img_rgb = cv.cvtColor(img, cv.COLOR_BGR2RGB)</span></span>
<span class="line"><span>plt.imshow(img_rgb)</span></span>
<span class="line"><span>plt.show()</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/06/image-7.png" alt=""></p><h3 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to 更多信息">​</a></h3>`,35)),s("p",null,[a[14]||(a[14]=n("关于 OpenCV 的更多细节可以在")),e(p,{href:"https://docs.opencv.org/4.5.2/index.html"},{default:t(()=>a[13]||(a[13]=[n("在线文档")])),_:1}),a[15]||(a[15]=n("中找到。"))]),a[36]||(a[36]=s("p",null,"感谢阅读。",-1)),a[37]||(a[37]=s("hr",null,null,-1)),s("p",null,[a[17]||(a[17]=n("via: ")),e(p,{href:"https://fedoramagazine.org/use-opencv-on-fedora-linux-part-1/"},{default:t(()=>a[16]||(a[16]=[n("https://fedoramagazine.org/use-opencv-on-fedora-linux-part-1/")])),_:1})]),s("p",null,[a[22]||(a[22]=n("作者：")),e(p,{href:"https://fedoramagazine.org/author/thunderbirdtr/"},{default:t(()=>a[18]||(a[18]=[n("Onuralp SEZER")])),_:1}),a[23]||(a[23]=n(" 选题：")),e(p,{href:"https://github.com/lujun9972"},{default:t(()=>a[19]||(a[19]=[n("lujun9972")])),_:1}),a[24]||(a[24]=n(" 译者：")),e(p,{href:"https://github.com/geekpi"},{default:t(()=>a[20]||(a[20]=[n("geekpi")])),_:1}),a[25]||(a[25]=n(" 校对：")),e(p,{href:"https://github.com/wxy"},{default:t(()=>a[21]||(a[21]=[n("wxy")])),_:1})]),s("p",null,[a[28]||(a[28]=n("本文由 ")),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>a[26]||(a[26]=[n("LCTT")])),_:1}),a[29]||(a[29]=n(" 原创编译，")),e(p,{href:"https://linux.cn/"},{default:t(()=>a[27]||(a[27]=[n("Linux中国")])),_:1}),a[30]||(a[30]=n(" 荣誉推出"))])])}const x=l(g,[["render",c]]);export{f as __pageData,x as default};
